              fileContent += `Flagged: ${unavailableWebsites.length} (${checkedWebsites.length > 0 ? ((unavailableWebsites.length / checkedWebsites.length) * 100).toFixed(1) : 0}%)\n`;
              fileContent += `Status: Test interrupted by user (Ctrl+C)\n`;
